examples.code:
students = [
    {"name": "Aditi", "score": 92, "branch": "CSE"},
    {"name": "Dev", "score": 78, "branch": "IT"},
    {"name": "Ishaan", "score": 85, "branch": "CSE"},
    {"name": "Kavya", "score": 95, "branch": "ECE"}
]

# Dict of top performers (score >= 85)
honor_roll = {s["name"]: s["score"] for s in students if s["score"] >= 85}
print("Honor Roll:", honor_roll)

# Unique branches using Set comprehension
branches = {s["branch"] for s in students}
print("Distinct branches:", branches)

