examples.code:
BEGIN;

-- Step 1: Deduct from Account A
UPDATE accounts 
SET balance = balance - 1000 
WHERE account_id = 'ACC_1001' AND balance >= 1000;

-- Step 2: Credit to Account B
UPDATE accounts 
SET balance = balance + 1000 
WHERE account_id = 'ACC_2002';

-- If any error occurs or balance insufficient, execute:
-- ROLLBACK;
-- Otherwise, persist changes permanently:
COMMIT;

-- Set isolation level to SERIALIZABLE to prevent Dirty, Non-repeatable, and Phantom reads
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
BEGIN;
SELECT SUM(balance) FROM accounts WHERE branch_id = 4;
COMMIT;

