        if (c == '(' || c == '{' || c == '[') stack[++top] = c;
        else {
            if (top == -1) { printf("false\n"); return 0; }
            char prev = stack[top--];
            if (c == ')' && prev != '(') { printf("false\n"); return 0; }
            if (c == '}' && prev != '{') { printf("false\n"); return 0; }
            if (c == ']' && prev != '[') { printf("false\n"); return 0; }
        }
    }
    printf("%s\n", top == -1 ? "true" : "false");
    return 0;
}

