int main() {
    int n; if (!(cin >> n)) return 0;
    vector<int> h(n);
    for(int i = 0; i < n; i++) cin >> h[i];
    if (n <= 2) { cout << 0 << endl; return 0; }
    int l = 0, r = n - 1;
    int l_max = h[l], r_max = h[r];
    long long water = 0;
    while (l < r) {
        if (l_max < r_max) {
            l++;
            l_max = max(l_max, h[l]);
            water += l_max - h[l];
        } else {
            r--;
            r_max = max(r_max, h[r]);
            water += r_max - h[r];
        }
    }
    cout << water << endl;
    return 0;
}

